for(const project of projects){const dir=mkdtempSync(join(tmpdir(),'prometeu-context-'));let indexed;try{
 for(const[path,source]of Object.entries(project.files)){mkdirSync(dirname(join(dir,path)),{recursive:true});writeFileSync(join(dir,path),source);}
 indexed=await Project.init(dir,{silent:true,config:{exclude:[]}});const result=await indexed.indexAll();if(!result.success)throw Error('Index failed');const queries=indexed.queries;
 project.nodes=queries.getAllNodes().map(strip);project.edges=queries.getOutgoingEdgesFrom(project.nodes.map(n=>n.id));project.generated=Object.keys(project.files).filter(queries.generatedPredicateFor(Object.keys(project.files)));project.deprioritized=[];
 const answers=new Map();for(const[method,request]of [['searchNodes',(text,opt)=>({kind:'text',query:text,kinds:opt?.kinds??[],limit:opt?.limit??50})],['findNodesByExactName',(names,opt)=>({kind:'exactNames',names,kinds:opt?.kinds??[],limit:opt?.limit??50})],['findNodesByNameSubstring',(text,opt)=>({kind:'substring',text,kinds:opt?.kinds??[],exclude_prefix:opt?.excludePrefix??false,limit:opt?.limit??30})]]){const original=queries[method].bind(queries);queries[method]=(...args)=>{const output=original(...args),key=request(...args);answers.set(JSON.stringify(key),{request:key,hits:output.map(hit=>({id:hit.node.id,score:hit.score}))});return output;};}
 const builder=new ContextBuilder(dir,queries,indexed.traverser);project.cases=[];
 for(const query of defaultQueries){for(const opt of options){const graph=await builder.findRelevantContext(query,opt);project.cases.push({query,options:opt,expected:cleanContext(graph)});}const buildOptions={maxCodeBlocks:3,maxCodeBlockSize:90};const context=await builder.buildContext(query,{...buildOptions,format:'structured'});const markdown=await builder.buildContext(query,{...buildOptions,format:'markdown'});const json=await builder.buildContext(query,{...buildOptions,format:'json'});project.cases.push({query,buildOptions,context:cleanContext(context),markdown:prose(markdown),json:JSON.parse(json),tree:formatSubgraphTree(context.subgraph,context.entryPoints)});}
 project.answers=[...answers.values()];console.log(project.id,project.nodes.length,project.edges.length,project.cases.length);
}finally{indexed?.close();rmSync(dir,{recursive:true,force:true});}}
